const axios = require('axios');

async function getConfidentJustinBieber(m) {
  const url = 'https://ppev.co.za/grab/json.php';
  const query = 'Confident Justin Bieber';

  try {
    const response = await axios.get(url, {
      params: {
        q: query
      },
      headers: {
        'Accept': 'application/json, text/javascript, */*; q=0.01',
        'X-Requested-With': 'XMLHttpRequest',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 12; Infinix X665E Build/SP1A.210812.016; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/150.0.7871.181 Mobile Safari/537.36',
        'Referer': 'https://ppev.co.za/search/confident-justin-bieber'
      }
    });

    if (response.data && response.data.items && response.data.items.length > 0) {
      let message = `Hasil pencarian untuk "${response.data.query}":\n\n`;
      response.data.items.forEach((item, index) => {
        message += `${index + 1}. Judul: ${item.title}\n`;
        message += `   Artis: ${item.artist}\n`;
        message += `   Views: ${item.views}\n`;
        message += `   Durasi: ${item.duration}\n`;
        message += `   Thumbnail: ${item.thumbnail}\n\n`;
      });
      await m.reply(message.trim());
    } else {
      await m.reply('Tidak ada hasil yang ditemukan.');
    }
  } catch (error) {
    await m.reply(`Terjadi kesalahan saat melakukan permintaan: ${error.message}`);
  }
}

// Contoh pemanggilan fungsi (asumsikan 'm' adalah objek pesan yang Anda terima)
